import { task, webhooks } from '@trigger.dev/sdk';
import { stripe } from './stripe';

export const payOrder = task({
  id: 'pay-order',
  run: async ({ orderId }: { orderId: string }) => {
    const waiter = await webhooks.waiter.create(stripe, {
      match: { 'event.data.object.metadata.orderId': orderId },
      idempotencyKey: `payment-${orderId}`,
    });
    const { event } = await webhooks.waiter.wait(waiter).unwrap();
    return event;
  },
});
import { webhooks } from '@trigger.dev/sdk';

export const internal = webhooks.endpoint.define({
  id: 'internal',
  source: webhooks.custom<{ id: string; message: string }>(
    {
      scheme: 'hmac',
      algorithm: 'sha256',
      encoding: 'hex',
      signatureHeader: 'x-webhook-signature',
      signingString: 'raw',
      idempotencyField: { from: 'body', name: 'id' },
    },
    { setupPrompt: 'Paste the signing secret under Settings > Webhooks.' }
  ),
});
